'use strict'

const { randomUUID } = require('node:crypto')
const Fastify = require('fastify')
const createBreaker = require('./circuitBreaker')
const listenMock = require('../mock-server')

/**
 * @typedef {Object} EventPayload
 * @property {string} id            Event_Identifier (UUID) generated by the Service
 * @property {string} name
 * @property {number|string} userId
 * @property {string} [details]
 */

/**
 * @typedef {Object} ErrorResponse
 * @property {'VALIDATION_ERROR'|'NOT_FOUND'|'INTERNAL_ERROR'|'UPSTREAM_ERROR'|'SERVICE_UNAVAILABLE'} error
 * @property {string} message
 */

const CODES = { 400: 'VALIDATION_ERROR', 404: 'NOT_FOUND', 500: 'INTERNAL_ERROR', 502: 'UPSTREAM_ERROR', 503: 'SERVICE_UNAVAILABLE' }
const UPSTREAM_FAILED = 'Event API request failed'

/**
 * Builds the Fastify app without binding a port.
 * @param {Object} [options]
 * @param {Object|boolean} [options.logger]      Fastify logger option. Default: { level: LOG_LEVEL || 'info' }.
 * @param {string} [options.eventApiUrl]         Event_API base URL. Default: EVENT_API_URL || 'http://event.com'.
 * @param {number} [options.upstreamTimeoutMs]   Upstream_Timeout. Default: 5000.
 * @param {typeof fetch} [options.fetch]         Used for every Event_API call. Default: globalThis.fetch, looked up per call.
 * @returns {import('fastify').FastifyInstance}
 */
function build({
  logger = { level: process.env.LOG_LEVEL || 'info' },
  eventApiUrl = process.env.EVENT_API_URL || 'http://event.com',
  upstreamTimeoutMs = 5000,
  fetch = (url, init) => globalThis.fetch(url, init),
} = {}) {
  const app = Fastify({ logger, ajv: { customOptions: { coerceTypes: false } } })

  /**
   * Creates an error that the error handler maps to an Error_Response.
   * @param {number} statusCode
   * @param {string} message
   * @returns {Error & { statusCode: number }}
   */
  function httpError(statusCode, message) {
    const err = new Error(message)
    err.statusCode = statusCode
    return err
  }

  /**
   * Calls the Event_API with the Upstream_Timeout. Does not check the status.
   * @param {string} path      e.g. '/getUsers'
   * @param {RequestInit} [init]
   * @returns {Promise<Response>}
   * @throws {Error} 502 'Event API request failed' on network error or timeout
   */
  async function callApi(path, init) {
    try {
      return await fetch(eventApiUrl + path, { ...init, signal: AbortSignal.timeout(upstreamTimeoutMs) })
    } catch {
      throw httpError(502, UPSTREAM_FAILED)
    }
  }

  /**
   * GETs a JSON body.
   * @param {string} path
   * @returns {Promise<any|null>}   null for an empty body
   * @throws {Error} 502 with upstreamStatus when the status is not 2xx
   */
  async function getJson(path) {
    const res = await callApi(path)
    if (!res.ok) {
      const err = httpError(502, UPSTREAM_FAILED)
      err.upstreamStatus = res.status
      throw err
    }
    // A body that fails mid-read (e.g. the timeout fires) is an Upstream_Failure too.
    const text = await res.text().catch(() => { throw httpError(502, UPSTREAM_FAILED) })
    return text === '' ? null : JSON.parse(text)
  }

  const breaker = createBreaker({
    send: (p) => callApi('/addEvent', {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify(p),
    }).then((r) => r.status),
    log: app.log,
  })
  app.addHook('onClose', async () => breaker.stop())

  app.setErrorHandler((err, request, reply) => {
    const s = err.statusCode
    const status = CODES[s] ? s : 500
    let message = err.message
    if (status === 400 && !err.validation) message = 'Request body must be a JSON object'
    if (status === 500) message = 'Internal server error'
    if (err.retryAfter) reply.header('Retry-After', err.retryAfter)
    if (status >= 500) request.log.error(err)
    reply.code(status).send({ error: CODES[status], message })
  })

  app.setNotFoundHandler((request, reply) => {
    reply.code(404).send({ error: 'NOT_FOUND', message: 'Route not found' })
  })

  app.get('/health', async () => ({ status: 'ok', circuitBreaker: breaker.state() }))

  app.get('/getUsers', async () => getJson('/getUsers'))

  app.get('/getEvents', async () => getJson('/getEvents'))

  app.get('/getEventsByUserId/:id', {
    schema: {
      params: {
        type: 'object',
        required: ['id'],
        properties: { id: { type: 'string', pattern: '^[A-Za-z0-9_-]+$' } },
      },
    },
  }, async (request) => {
    let user
    try {
      user = await getJson('/getUserById/' + request.params.id)
    } catch (err) {
      if (err.upstreamStatus === 404) throw httpError(404, 'User not found')
      throw err
    }
    if (user === null) throw httpError(404, 'User not found')
    return Promise.all(user.events.map(async (eventId) => {
      const event = await getJson('/getEventById/' + encodeURIComponent(eventId))
      if (event === null) throw httpError(502, 'Event API returned no event')
      return event
    }))
  })

  app.post('/addEvent', {
    schema: {
      body: {
        type: 'object',
        required: ['name', 'userId'],
        properties: {
          name: { type: 'string', minLength: 1 },
          userId: { anyOf: [{ type: 'integer', minimum: 1 }, { type: 'string', minLength: 1 }] },
          details: { type: 'string' },
        },
      },
    },
  }, async (request, reply) => {
    const { name, userId, details } = request.body
    const event = { id: randomUUID(), name, userId, ...(details !== undefined && { details }) }
    const status = await breaker.call(event)
    if (status < 200 || status > 299) throw httpError(502, UPSTREAM_FAILED)
    return reply.code(201).send(event)
  })

  return app
}

/**
 * Starts the mock interception, then the server, and wires graceful shutdown.
 * Exits with code 1 if the server cannot listen.
 * @returns {Promise<void>}
 */
async function start() {
  listenMock()
  const app = build()
  try {
    await app.listen({ port: process.env.PORT || 3000, host: process.env.HOST || '127.0.0.1' })
  } catch (err) {
    app.log.error(err)
    process.exit(1)
  }
  for (const signal of ['SIGTERM', 'SIGINT']) {
    process.once(signal, async () => {
      await app.close()
      process.exit(0)
    })
  }
}

if (require.main === module) start()

module.exports = build
